"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["279"],{90166(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fada_aplica_sem_configuracao","status":422,"titulo":"O processo que aplica o Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) precisa da configura\xe7\xe3o do FADA"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fada_aplica_sem_configuracao","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["A declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso diz que o processo **aplica** o fator, mas chegou sem a regra do fator (`regra.codigo`). O processo declara se aplica ou n\xe3o o Fator de Atenua\xe7\xe3o, como declara a cobran\xe7a da taxa de inscri\xe7\xe3o; aus\xeancia de configura\xe7\xe3o n\xe3o significa \\"sem Fator de Atenua\xe7\xe3o\\"."],"comoResolver":["- **Se o Fator de Atenua\xe7\xe3o se aplica:** envie junto da declara\xe7\xe3o a regra (`regra.codigo` e `regra.versao`), o multiplicador da nota (`fator`), a base legal (`baseLegal.id`, de onde v\xeam os munic\xedpios) e, se houver, o `teto`.\\n- **Se o Fator de Atenua\xe7\xe3o n\xe3o se aplica:** declare `aplica: false` e n\xe3o envie nenhum outro campo do fator."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);